SELECT FROM `tag` WHERE is_deleted = 0
AND (name LIKE CONCAT('%', #{keyword}, '%') OR slug LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY article_count DESC, id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM `tag`
WHERE name = #{name} AND is_deleted = 0
AND id != #{excludeId}

SELECT COUNT(*) FROM `tag`
WHERE slug = #{slug} AND is_deleted = 0
AND id != #{excludeId}
